using Markdig;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using YamlDotNet.Serialization;
using YamlDotNet.RepresentationModel;
namespace FluxDrop.Core;
public static class DataEngine {
 public static readonly string[] Ids=["jsonPretty","jsonMinify","jsonYAML","yamlJSON","csvJSON","jsonCSV","csvTSV","tsvCSV","markdownHTML"];
 public static JsonNode? Json(string text){using var doc=JsonDocument.Parse(text,new JsonDocumentOptions{MaxDepth=64});void Check(JsonElement e){if(e.ValueKind==JsonValueKind.Object){var keys=new HashSet<string>();foreach(var p in e.EnumerateObject()){if(!keys.Add(p.Name))throw new FormatException("Clave JSON duplicada: "+p.Name);Check(p.Value);}}else if(e.ValueKind==JsonValueKind.Array)foreach(var c in e.EnumerateArray())Check(c);}Check(doc.RootElement);return JsonNode.Parse(text);}
 public static List<List<string>> Csv(string text,char delimiter){var rows=new List<List<string>>();var row=new List<string>();var field=new StringBuilder();bool quoted=false,closed=false;for(int i=0;i<text.Length;i++){char c=text[i];if(quoted){if(c=='"'){if(i+1<text.Length&&text[i+1]=='"'){field.Append('"');i++;}else{quoted=false;closed=true;}}else field.Append(c);continue;}if(c=='"'){if(field.Length!=0||closed)throw new FormatException("Comillas CSV mal ubicadas.");quoted=true;}else if(c==delimiter){row.Add(field.ToString());field.Clear();closed=false;}else if(c is '\r' or '\n'){if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;row.Add(field.ToString());rows.Add(row);row=[];field.Clear();closed=false;}else{if(closed)throw new FormatException("Texto después de las comillas CSV.");field.Append(c);}}if(quoted)throw new FormatException("Campo CSV sin cerrar.");if(field.Length>0||row.Count>0||closed){row.Add(field.ToString());rows.Add(row);}if(rows.Count==0||rows.Any(r=>r.Count!=rows[0].Count))throw new FormatException("CSV vacío o con columnas desiguales.");return rows;}
 public static string WriteCsv(IEnumerable<IEnumerable<string>> rows,char delimiter)=>string.Join("\r\n",rows.Select(r=>string.Join(delimiter,r.Select(v=>v.IndexOfAny([delimiter,'"','\n','\r'])>=0?'"'+v.Replace("\"","\"\"")+'"':v))))+"\r\n";
 public static (string,string) Convert(string operation,string text,Options o){switch(operation){case "jsonPretty":case "jsonMinify":var node=Json(text);return ("json",node?.ToJsonString(new JsonSerializerOptions{WriteIndented=operation=="jsonPretty"})??"null");case "jsonYAML":var j=Json(text);
 var yaml=new YamlStream(new YamlDocument(ToYaml(j)));using(var writer=new StringWriter()){yaml.Save(writer,false);return("yaml",writer.ToString());}
 case "yamlJSON":var stream=new YamlStream();stream.Load(new StringReader(text));if(stream.Documents.Count!=1)throw new FormatException("Se requiere un documento YAML.");return("json",FromYaml(stream.Documents[0].RootNode,0)?.ToJsonString(Config.Json)??"null");
 case "csvJSON":var rows=Csv(text,o.Delimiter);if(o.Headers){var headers=rows[0];if(headers.Any(string.IsNullOrEmpty)||headers.Distinct().Count()!=headers.Count)throw new FormatException("Cabeceras vacías o duplicadas.");return("json",JsonSerializer.Serialize(rows.Skip(1).Select(r=>headers.Zip(r).ToDictionary(x=>x.First,x=>x.Second)),Config.Json));}return("json",JsonSerializer.Serialize(rows,Config.Json));
 case "jsonCSV":var array=Json(text) as JsonArray??throw new FormatException("Se requiere un array JSON.");if(array.Count==0)throw new FormatException("Array vacío.");List<List<string>> result=[];if(o.Headers){var first=array[0] as JsonObject??throw new FormatException("Se requieren objetos planos con valores de texto.");var keys=first.Select(p=>p.Key).ToList();result.Add(keys);foreach(var n in array){var obj=n as JsonObject??throw new FormatException("Objeto esperado.");if(obj.Count!=keys.Count||keys.Any(k=>!obj.ContainsKey(k)))throw new FormatException("Objetos con claves diferentes.");result.Add(keys.Select(k=>StringValue(obj[k])).ToList());}}else foreach(var n in array)result.Add((n as JsonArray??throw new FormatException("Array de arrays requerido.")).Select(StringValue).ToList());if(result.Any(r=>r.Count!=result[0].Count))throw new FormatException("Filas desiguales.");return("csv",WriteCsv(result,o.Delimiter));
 case "csvTSV":return("tsv",WriteCsv(Csv(text,o.Delimiter),'\t'));case "tsvCSV":return("csv",WriteCsv(Csv(text,'\t'),o.Delimiter));
 case "markdownHTML":return("html","<!doctype html><html lang=\"es\"><meta charset=\"utf-8\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; style-src 'unsafe-inline'\"><title>Documento</title><body>"+Markdig.Markdown.ToHtml(text,new Markdig.MarkdownPipelineBuilder().DisableHtml().Build())+"</body></html>");default:throw new NotSupportedException();}}
 private static string StringValue(JsonNode? n)=>n is JsonValue v&&v.TryGetValue<string>(out var s)?s:throw new FormatException("CSV conserva solo valores string; no se convierten tipos silenciosamente.");
 private static YamlNode ToYaml(JsonNode? n)=>n switch {JsonObject obj=>new YamlMappingNode(obj.Select(p=>new KeyValuePair<YamlNode,YamlNode>(new YamlScalarNode(p.Key){Style=YamlDotNet.Core.ScalarStyle.DoubleQuoted},ToYaml(p.Value)))),JsonArray arr=>new YamlSequenceNode(arr.Select(ToYaml)),JsonValue v when v.TryGetValue<string>(out var s)=>new YamlScalarNode(s){Style=YamlDotNet.Core.ScalarStyle.DoubleQuoted},_=>new YamlScalarNode(n?.ToJsonString()??"null")};
 private static JsonNode? FromYaml(YamlNode n,int depth){if(depth>64||!n.Anchor.IsEmpty||(!n.Tag.IsEmpty&&!n.Tag.IsNonSpecific))throw new FormatException("YAML: no se admiten alias, anchors ni tags.");if(n is YamlMappingNode m){var o=new JsonObject();foreach(var p in m.Children){if(p.Key is not YamlScalarNode key||key.Value==null||o.ContainsKey(key.Value))throw new FormatException("Clave YAML no textual o duplicada.");o.Add(key.Value,FromYaml(p.Value,depth+1));}return o;}if(n is YamlSequenceNode a)return new JsonArray(a.Children.Select(c=>FromYaml(c,depth+1)).ToArray());if(n is not YamlScalarNode scalar)throw new FormatException("YAML no compatible.");string value=scalar.Value??"";if(scalar.Style is YamlDotNet.Core.ScalarStyle.DoubleQuoted or YamlDotNet.Core.ScalarStyle.SingleQuoted)return JsonValue.Create(value);if(value is "null" or "~")return null;if(value is "true" or "false")return JsonValue.Create(value=="true");try{var parsed=JsonNode.Parse(value);if(parsed is JsonValue v&&v.GetValueKind()==JsonValueKind.Number)return parsed;}catch(JsonException){}if(DateTime.TryParse(value,out _)||value is ".inf" or ".nan")throw new FormatException("Fecha o número YAML ambiguo: usa comillas.");return JsonValue.Create(value);}
}
